    return db.session.get(User, int(user_id))


redis_client = redis.Redis(
    host="localhost", port=6379, db=0, decode_responses=True
)

MAX_FAILED = 5
LOCK_SECONDS = 3600


def is_locked(username):
    try:
        return redis_client.exists(f"lockout:{username}") == 1
    except redis.RedisError:
        app.logger.exception("Redis unavailable during lockout check")
        return False  # MVP fail-open; use fail-closed if stricter security is required


def record_failure(username):
    try:
        attempt_key = f"attempt:{username}"
        lock_key = f"lockout:{username}"
        pipe = redis_client.pipeline()
        pipe.incr(attempt_key)
        pipe.expire(attempt_key, LOCK_SECONDS)
        count, _ = pipe.execute()
        if int(count) >= MAX_FAILED:
            redis_client.setex(lock_key, LOCK_SECONDS, "1")
    except redis.RedisError:
        app.logger.exception("Redis unavailable while recording failed login")


def clear_failures(username):
    try:
        redis_client.delete(f"attempt:{username}", f"lockout:{username}")
    except redis.RedisError:
        app.logger.exception("Redis unavailable while clearing login failures")


@app.post("/register")
def register():
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""

    if not username or not password:
        return jsonify(error="Username and password are required"), 400

    if len(username) > 50 or len(password) > 100:
        return jsonify(error="Username or password is too long"), 400

    if User.query.filter_by(username=username).first():
        return jsonify(error="Username already exists"), 409

    user = User(username=username)
    user.set_password(password)
    db.session.add(user)
    db.session.commit()

    return jsonify(message="User registered successfully"), 201


@app.post("/login")
def login():
    data = request.get_json(silent=True) or {}
    username = (data.get("username") or "").strip()
    password = data.get("password") or ""

    if not username or not password:
        return jsonify(error="Username and password are required"), 400

    if len(username) > 50 or len(password) > 100:
        return jsonify(error="Invalid username or password"), 401

    if is_locked(username):
        return jsonify(error="Account temporarily locked. Try again later."), 423

    user = User.query.filter_by(username=username).first()

    if user is None or not user.check_password(password):
        record_failure(username)
        return jsonify(error="Invalid username or password"), 401

    clear_failures(username)
    login_user(user)
    session.permanent = True

    return jsonify(message="Logged in", user_id=user.id), 200


@app.post("/logout")
@login_required
def logout():
    logout_user()
    return jsonify(message="Logged out"), 200


@app.get("/transactions")
@login_required
def transactions():
    return jsonify(user_id=current_user.id, message="Protected transaction route")
